:root{--color-bg:#fff8f5;--color-surface:#ffffff;--color-text:#3a2a2a;--color-text-muted:#6b5555;--color-primary:#9b2c54;--color-primary-dark:#7a2143;--color-accent-on-dark:#f6c8dc;--color-dark-bg:#3a1f2b;--color-border:#e8d6da;--font-base:'Trebuchet MS', Verdana, sans-serif;--font-heading:'Trebuchet MS', Verdana, sans-serif;--space-xs:0.5rem;--space-sm:1rem;--space-md:1.5rem;--space-lg:2.5rem;--space-xl:4rem;--radius:0.6rem;--max-width:75rem;}
*{box-sizing:border-box;}
html{scroll-behavior:smooth;}
body{margin:0;font-family:var(--font-base);background-color:var(--color-bg);color:var(--color-text);line-height:1.6;}
h1,h2,h3{font-family:var(--font-heading);color:var(--color-primary);line-height:1.2;margin-top:0;}
p{margin-top:0;}
a{color:var(--color-primary);text-decoration:underline;}
a:hover{color:var(--color-primary-dark);}
a:focus-visible,button:focus-visible,input:focus-visible,textarea:focus-visible{outline:3px solid var(--color-primary-dark);outline-offset:2px;}
.container{max-width:var(--max-width);margin:0 auto;padding:0 1.25rem;}
header{background-color:var(--color-surface);border-bottom:1px solid var(--color-border);}
.header-inner{display:flex;flex-wrap:wrap;align-items:center;justify-content:space-between;gap:var(--space-sm);padding:var(--space-sm) 0;}
.logo{font-family:'Trebuchet MS', Verdana, sans-serif;font-weight:800;text-decoration:none;color:var(--color-primary);font-size:clamp(1.1rem,4vw,1.6rem);text-shadow:2px 2px 0 var(--color-accent-on-dark);transform:rotate(-2deg);display:inline-block;letter-spacing:0.02em;}
.logo:hover{color:var(--color-primary-dark);}
nav[aria-label='Main'] ul{list-style:none;display:flex;flex-wrap:wrap;gap:var(--space-sm);margin:0;padding:0;}
nav[aria-label='Main'] a{text-decoration:none;font-weight:700;color:var(--color-text);padding:0.5rem 0.25rem;}
nav[aria-label='Main'] a:hover{color:var(--color-primary);}
main{display:block;}
section{padding:var(--space-lg) 0;}
.card{background-color:var(--color-surface);border:1px solid var(--color-border);border-radius:var(--radius);padding:var(--space-md);box-shadow:0 2px 6px rgba(58,42,42,0.08);}
.grid{display:grid;gap:var(--space-md);grid-template-columns:1fr;}
.btn{display:inline-flex;align-items:center;justify-content:center;min-height:44px;padding:0.75rem 1.5rem;background-color:var(--color-primary);color:#ffffff;border:none;border-radius:var(--radius);font-size:1rem;font-weight:700;text-decoration:none;cursor:pointer;}
.btn:hover{background-color:var(--color-primary-dark);}
form{display:flex;flex-direction:column;gap:var(--space-sm);}
.form-field{display:flex;flex-direction:column;gap:0.35rem;}
label{font-weight:700;color:var(--color-text);}
input,textarea{min-height:44px;padding:0.6rem 0.8rem;border:1px solid var(--color-border);border-radius:var(--radius);font-family:inherit;font-size:1rem;background-color:var(--color-surface);color:var(--color-text);}
textarea{min-height:8rem;resize:vertical;}
input:focus,textarea:focus{border-color:var(--color-primary);}
table{width:100%;border-collapse:collapse;}
table caption{text-align:left;font-weight:700;margin-bottom:var(--space-xs);}
th,td{text-align:left;padding:0.6rem 0.8rem;border-bottom:1px solid var(--color-border);}
th{color:var(--color-primary);}
img{max-width:100%;height:auto;display:block;border-radius:var(--radius);}
footer{background-color:var(--color-dark-bg);color:var(--color-accent-on-dark);padding:var(--space-lg) 0;}
footer .footer-brand{font-weight:800;font-size:1.1rem;color:var(--color-accent-on-dark);margin-bottom:var(--space-xs);}
footer p{margin:0.25rem 0;color:var(--color-accent-on-dark);}
@media (max-width:600px){.header-inner{flex-direction:column;align-items:flex-start;}nav[aria-label='Main'] ul{flex-direction:column;gap:0.25rem;width:100%;}.container{padding:0 1rem;}section{padding:var(--space-md) 0;}}
@media (min-width:601px){.grid-2{grid-template-columns:repeat(2,1fr);}.grid-3{grid-template-columns:repeat(3,1fr);}.header-inner{flex-wrap:nowrap;}}

